PGPASSWORD="$PGPASSWORD" runtime exec -e PGPASSWORD="$PGPASSWORD" leadscorer-db psql -U "$PGUSER" -d "$PGDATABASE" -tA -c "
SELECT 'gerente com mais ciclos', m.username, COUNT(*) AS ciclos,
       COUNT(*) FILTER (WHERE e.outcome='won') AS won,
       COUNT(*) FILTER (WHERE e.closed_at IS NULL) AS abertos
FROM engagements e
JOIN sales_agents a ON a.id = e.sales_agent_id
JOIN sales_managers m ON m.id = a.sales_manager_id
GROUP BY m.username ORDER BY ciclos DESC LIMIT 3;
SELECT 'opps engaging', COUNT(*) FROM opportunities WHERE status='engaging';
SELECT 'ciclos abertos totais', COUNT(*) FROM engagements WHERE closed_at IS NULL;
SELECT 'devolvidos (closed sem outcome)', COUNT(*) FROM engagements WHERE closed_at IS NOT NULL AND outcome IS NULL;
"

